1	package com.example.starter.invoice;
2	
3	import java.math.BigDecimal;
4	import java.util.List;
5	import java.util.UUID;
6	
7	import com.example.starter.common.ApiException;
8	import com.example.starter.credit.CreditService;
9	import com.example.starter.idempotency.IdempotencyService;
10	import com.fasterxml.jackson.core.JsonProcessingException;
11	import com.fasterxml.jackson.databind.ObjectMapper;
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.support.TransactionTemplate;
16	
17	/**
18	 * 蓝字发票服务：开具→交付→（可红冲）→归档。
19	 * 开票按 requestId 幂等；可用额度恰等于开票金额合法，超出拒绝且额度不变；
20	 * 并发开票通过授信账户行锁串行校验，不得合计超额。
21	 * 归档为终态：重复归档幂等成功；归档后只许红冲，禁止修改原始票面。
22	 */
23	@Service
24	public class InvoiceService {
25	
26	    static final String ENDPOINT_ISSUE = "ISSUE_BLUE";
27	
28	    private final JdbcTemplate jdbc;
29	    private final CreditService creditService;
30	    private final IdempotencyService idempotencyService;
31	    private final TransactionTemplate transactionTemplate;
32	    private final ObjectMapper objectMapper;
33	
34	    public InvoiceService(JdbcTemplate jdbc, CreditService creditService,
35	                          IdempotencyService idempotencyService,
36	                          TransactionTemplate transactionTemplate, ObjectMapper objectMapper) {
37	        this.jdbc = jdbc;
38	        this.creditService = creditService;
39	        this.idempotencyService = idempotencyService;
40	        this.transactionTemplate = transactionTemplate;
41	        this.objectMapper = objectMapper;
42	    }
43	
44	    /**
45	     * 开具蓝票（幂等）。同键同参返回首次结果，同键异参返回 409 且额度不变。
46	     */
47	    public IssueResponse issueBlue(IssueBlueInvoiceRequest request) {
48	        validateIssue(request);
49	        String fingerprint = idempotencyService.fingerprint(ENDPOINT_ISSUE, request);
50	        var existing = idempotencyService.find(ENDPOINT_ISSUE, request.requestId());
51	        if (existing.isPresent()) {
52	            return deserialize(idempotencyService.replayOrReject(ENDPOINT_ISSUE, request, request.requestId()).body());
53	        }
54	        try {
55	            return transactionTemplate.execute(status -> doIssueBlue(request, fingerprint));
56	        } catch (DuplicateKeyException e) {
57	            // 并发同键：首次请求已提交，重放其结果
58	            return deserialize(idempotencyService.replayOrReject(ENDPOINT_ISSUE, request, request.requestId()).body());
59	        }
60	    }
61	
62	    private IssueResponse doIssueBlue(IssueBlueInvoiceRequest request, String fingerprint) {
63	        idempotencyService.begin(ENDPOINT_ISSUE, request.requestId(), fingerprint);
64	        BigDecimal totalAmount = request.lines().stream()
65	                .map(LineRequest::amount)
66	                .reduce(BigDecimal.ZERO, BigDecimal::add);
67	        // 串行校验：锁定授信账户后再复算可用额度
68	        creditService.lockAccount(request.sellerId());
69	        BigDecimal available = creditService.computeAvailable(request.sellerId());
70	        if (totalAmount.compareTo(available) > 0) {
71	            throw ApiException.conflict("INSUFFICIENT_CREDIT",
72	                    "可用额度不足：可用 " + available + "，申请 " + totalAmount + "，额度不变");
73	        }
74	        long invoiceId = insertInvoice("INV", "BLUE", request.sellerId(), request.buyerId(),
75	                request.buyerBooked(), totalAmount, "ISSUED", null);
76	        String invoiceNo = jdbc.queryForObject(
77	                "SELECT invoice_no FROM invoice WHERE id = ?", String.class, invoiceId);
78	        int lineNo = 1;
79	        for (LineRequest line : request.lines()) {
80	            jdbc.update(
81	                    "INSERT INTO invoice_line (invoice_id, line_no, item_name, amount) VALUES (?, ?, ?, ?)",
82	                    invoiceId, lineNo++, line.itemName(), line.amount());
83	        }
84	        creditService.appendLedger(request.sellerId(), totalAmount.negate(), "ISSUE", invoiceNo,
85	                available.subtract(totalAmount));
86	        IssueResponse response = new IssueResponse(invoiceNo, "ISSUED", totalAmount,
87	                available.subtract(totalAmount));
88	        idempotencyService.complete(ENDPOINT_ISSUE, request.requestId(), 200, response);
89	        return response;
90	    }
91	
92	    /**
93	     * 交付蓝票：ISSUED→DELIVERED；重复交付幂等成功；终态（已红冲/已归档）返回 409。
94	     */
95	    public ActionResponse deliver(String invoiceNo) {
96	        return transactionTemplate.execute(status -> {
97	            InvoiceRow invoice = lockByNo(invoiceNo);
98	            if (!"BLUE".equals(invoice.kind())) {
99	                throw ApiException.badRequest("NOT_BLUE_INVOICE", "非蓝字发票: " + invoiceNo);
100	            }
101	            switch (invoice.status()) {
102	                case "DELIVERED" -> {
103	                    return new ActionResponse(invoiceNo, "DELIVERED",
104	                            creditService.computeAvailable(invoice.sellerId()));
105	                }
106	                case "ISSUED" -> {
107	                    jdbc.update("UPDATE invoice SET status = 'DELIVERED', updated_at = CURRENT_TIMESTAMP"
108	                            + " WHERE id = ?", invoice.id());
109	                    return new ActionResponse(invoiceNo, "DELIVERED",
110	                            creditService.computeAvailable(invoice.sellerId()));
111	                }
112	                default -> throw ApiException.conflict("INVALID_STATE",
113	                        "当前状态 " + invoice.status() + " 不允许交付");
114	            }
115	        });
116	    }
117	
118	    /**
119	     * 归档蓝票：DELIVERED/PARTIAL_RED→ARCHIVED 并释放占用额度；重复归档幂等成功；
120	     * 未交付或已全额红冲（终态）返回 409。
121	     */
122	    public ActionResponse archive(String invoiceNo) {
123	        return transactionTemplate.execute(status -> {
124	            InvoiceRow invoice = lockByNo(invoiceNo);
125	            if (!"BLUE".equals(invoice.kind())) {
126	                throw ApiException.badRequest("NOT_BLUE_INVOICE", "非蓝字发票: " + invoiceNo);
127	            }
128	            switch (invoice.status()) {
129	                case "ARCHIVED" -> {
130	                    // 重复归档：幂等成功，不重复释放额度
131	                    return new ActionResponse(invoiceNo, "ARCHIVED",
132	                            creditService.computeAvailable(invoice.sellerId()));
133	                }
134	                case "DELIVERED", "PARTIAL_RED" -> {
135	                    creditService.lockAccount(invoice.sellerId());
136	                    BigDecimal available = creditService.computeAvailable(invoice.sellerId());
137	                    jdbc.update("UPDATE invoice SET status = 'ARCHIVED', updated_at = CURRENT_TIMESTAMP"
138	                            + " WHERE id = ?", invoice.id());
139	                    creditService.appendLedger(invoice.sellerId(), invoice.totalAmount(), "ARCHIVE",
140	                            invoiceNo, available.add(invoice.totalAmount()));
141	                    return new ActionResponse(invoiceNo, "ARCHIVED",
142	                            available.add(invoice.totalAmount()));
143	                }
144	                default -> throw ApiException.conflict("INVALID_STATE",
145	                        "当前状态 " + invoice.status() + " 不允许归档");
146	            }
147	        });
148	    }
149	
150	    /**
151	     * 查询发票详情：票面、行项目及红冲链（引用本票的红票），重复查询结果稳定。
152	     */
153	    public InvoiceView getInvoice(String invoiceNo) {
154	        InvoiceRow invoice = findByNo(invoiceNo);
155	        List<LineView> lines = jdbc.query(
156	                "SELECT line_no, item_name, amount, red_flushed_amount FROM invoice_line"
157	                        + " WHERE invoice_id = ? ORDER BY line_no",
158	                (rs, rowNum) -> new LineView(rs.getInt("line_no"), rs.getString("item_name"),
159	                        rs.getBigDecimal("amount"), rs.getBigDecimal("red_flushed_amount")),
160	                invoice.id());
161	        List<RedInvoiceRef> redChain = jdbc.query(
162	                "SELECT invoice_no, total_amount, created_at FROM invoice"
163	                        + " WHERE kind = 'RED' AND blue_invoice_no = ? ORDER BY id",
164	                (rs, rowNum) -> new RedInvoiceRef(rs.getString("invoice_no"),
165	                        rs.getBigDecimal("total_amount"), rs.getTimestamp("created_at").toLocalDateTime()),
166	                invoiceNo);
167	        return new InvoiceView(invoice.invoiceNo(), invoice.kind(), invoice.sellerId(), invoice.buyerId(),
168	                invoice.buyerBooked(), invoice.totalAmount(), invoice.redFlushedAmount(), invoice.status(),
169	                invoice.blueInvoiceNo(), lines, redChain);
170	    }
171	
172	    private void validateIssue(IssueBlueInvoiceRequest request) {
173	        if (request.requestId() == null || request.requestId().isBlank()) {
174	            throw ApiException.badRequest("VALIDATION_FAILED", "requestId 不能为空");
175	        }
176	        if (request.sellerId() == null || request.sellerId().isBlank()
177	                || request.buyerId() == null || request.buyerId().isBlank()) {
178	            throw ApiException.badRequest("VALIDATION_FAILED", "sellerId/buyerId 不能为空");
179	        }
180	        if (request.lines() == null || request.lines().isEmpty()) {
181	            throw ApiException.badRequest("VALIDATION_FAILED", "行项目不能为空");
182	        }
183	        for (LineRequest line : request.lines()) {
184	            if (line.itemName() == null || line.itemName().isBlank()
185	                    || line.amount() == null || line.amount().compareTo(BigDecimal.ZERO) <= 0) {
186	                throw ApiException.badRequest("VALIDATION_FAILED", "行项目名称不能为空且金额必须为正数");
187	            }
188	        }
189	    }
190	
191	    /**
192	     * 插入发票主行并回写正式发票号码（前缀+主键序号）。
193	     */
194	    long insertInvoice(String noPrefix, String kind, String sellerId, String buyerId, boolean buyerBooked,
195	                       BigDecimal totalAmount, String status, String blueInvoiceNo) {
196	        String tempNo = "TMP-" + UUID.randomUUID();
197	        jdbc.update(
198	                "INSERT INTO invoice (invoice_no, kind, seller_id, buyer_id, buyer_booked, total_amount,"
199	                        + " status, blue_invoice_no) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
200	                tempNo, kind, sellerId, buyerId, buyerBooked, totalAmount, status, blueInvoiceNo);
201	        Long id = jdbc.queryForObject("SELECT id FROM invoice WHERE invoice_no = ?", Long.class, tempNo);
202	        String invoiceNo = noPrefix + String.format("%08d", id);
203	        jdbc.update("UPDATE invoice SET invoice_no = ? WHERE id = ?", invoiceNo, id);
204	        return id;
205	    }
206	
207	    /**
208	     * 按发票号加行级悲观锁读取（须在事务内调用）。
209	     */
210	    InvoiceRow lockByNo(String invoiceNo) {
211	        return jdbc.query(
212	                        "SELECT id, invoice_no, kind, seller_id, buyer_id, buyer_booked, total_amount,"
213	                                + " red_flushed_amount, status, blue_invoice_no FROM invoice"
214	                                + " WHERE invoice_no = ? FOR UPDATE",
215	                        (rs, rowNum) -> mapRow(rs), invoiceNo)
216	                .stream()
217	                .findFirst()
218	                .orElseThrow(() -> ApiException.notFound("INVOICE_NOT_FOUND", "发票不存在: " + invoiceNo));
219	    }
220	
221	    InvoiceRow findByNo(String invoiceNo) {
222	        return jdbc.query(
223	                        "SELECT id, invoice_no, kind, seller_id, buyer_id, buyer_booked, total_amount,"
224	                                + " red_flushed_amount, status, blue_invoice_no FROM invoice WHERE invoice_no = ?",
225	                        (rs, rowNum) -> mapRow(rs), invoiceNo)
226	                .stream()
227	                .findFirst()
228	                .orElseThrow(() -> ApiException.notFound("INVOICE_NOT_FOUND", "发票不存在: " + invoiceNo));
229	    }
230	
231	    private InvoiceRow mapRow(java.sql.ResultSet rs) throws java.sql.SQLException {
232	        return new InvoiceRow(rs.getLong("id"), rs.getString("invoice_no"), rs.getString("kind"),
233	                rs.getString("seller_id"), rs.getString("buyer_id"), rs.getBoolean("buyer_booked"),
234	                rs.getBigDecimal("total_amount"), rs.getBigDecimal("red_flushed_amount"),
235	                rs.getString("status"), rs.getString("blue_invoice_no"));
236	    }
237	
238	    private IssueResponse deserialize(String body) {
239	        try {
240	            return objectMapper.readValue(body, IssueResponse.class);
241	        } catch (JsonProcessingException e) {
242	            throw new IllegalStateException("幂等响应反序列化失败", e);
243	        }
244	    }
245	
246	    /**
247	     * 发票主行内部视图。
248	     */
249	    record InvoiceRow(long id, String invoiceNo, String kind, String sellerId, String buyerId,
250	                      boolean buyerBooked, BigDecimal totalAmount, BigDecimal redFlushedAmount,
251	                      String status, String blueInvoiceNo) {
252	    }
253	
254	    /**
255	     * 开票请求行项目。
256	     */
257	    public record LineRequest(String itemName, BigDecimal amount) {
258	    }
259	
260	    /**
261	     * 开票请求（幂等指纹覆盖全部字段）。
262	     */
263	    public record IssueBlueInvoiceRequest(String requestId, String sellerId, String buyerId,
264	                                          boolean buyerBooked, List<LineRequest> lines) {
265	    }
266	
267	    /**
268	     * 开票响应。
269	     */
270	    public record IssueResponse(String invoiceNo, String status, BigDecimal totalAmount,
271	                                BigDecimal availableLimit) {
272	    }
273	
274	    /**
275	     * 状态流转响应。
276	     */
277	    public record ActionResponse(String invoiceNo, String status, BigDecimal availableLimit) {
278	    }
279	
280	    /**
281	     * 行项目视图。
282	     */
283	    public record LineView(int lineNo, String itemName, BigDecimal amount, BigDecimal redFlushedAmount) {
284	    }
285	
286	    /**
287	     * 红冲链中的红票引用。
288	     */
289	    public record RedInvoiceRef(String invoiceNo, BigDecimal amount, java.time.LocalDateTime createdAt) {
290	    }
291	
292	    /**
293	     * 发票详情视图。
294	     */
295	    public record InvoiceView(String invoiceNo, String kind, String sellerId, String buyerId,
296	                              boolean buyerBooked, BigDecimal totalAmount, BigDecimal redFlushedAmount,
297	                              String status, String blueInvoiceNo, List<LineView> lines,
298	                              List<RedInvoiceRef> redChain) {
299	    }
300	}
