/**
 * 行可申请余额：行金额−已红冲−在途部分红冲；存在在途全额申请时整行视为被占。
 */
private BigDecimal effectiveLineAvailable(long blueInvoiceId, LineRow line) {
    Integer fullPending = jdbc.queryForObject(
            "SELECT COUNT(*) FROM red_flush_request"
                    + " WHERE blue_invoice_id = ? AND status = 'PENDING' AND flush_type = 'FULL'",
            Integer.class, blueInvoiceId);
    if (fullPending != null && fullPending > 0) {
        return BigDecimal.ZERO;
    }
    BigDecimal pendingLine = jdbc.queryForObject(
            "SELECT COALESCE(SUM(rl.amount), 0) FROM red_flush_line rl"
                    + " JOIN red_flush_request r ON rl.request_id = r.id"
                    + " WHERE r.blue_invoice_id = ? AND r.status = 'PENDING' AND rl.line_no = ?",
            BigDecimal.class, blueInvoiceId, line.lineNo());
    if (pendingLine == null) {
        pendingLine = BigDecimal.ZERO;
    }
    return line.amount().subtract(line.redFlushedAmount()).subtract(pendingLine);
}

